import test from "node:test";
import assert from "node:assert/strict";
import { mapLegacyFact, parseLegacyFacts, stripLegacyBlock } from "../lib/legacy-profile.js";

const BODY = `# My rules

Keep answers short.

<!-- dsh:user-profile:begin -->

## What the assistant has learned about this user

- 2026-11-20 — 我叫林舟
- 2026-11-21 — 对花生过敏
- 2026-11-22 — 喜欢简洁的回答

<!-- dsh:user-profile:end -->

End of my notes.
`;

test("parseLegacyFacts reads dated and bare bullets", () => {
	const facts = parseLegacyFacts(BODY);
	assert.deepEqual(facts.map((fact) => fact.text), ["我叫林舟", "对花生过敏", "喜欢简洁的回答"]);
	assert.equal(facts[0].date, "2026-11-20");
});

test("stripLegacyBlock keeps the user's prose", () => {
	const body = stripLegacyBlock(BODY);
	assert.equal(body.includes("dsh:user-profile"), false);
	assert.equal(body.includes("Keep answers short."), true);
	assert.equal(body.includes("End of my notes."), true);
});

test("mapLegacyFact maps explicit facts and falls back to note", () => {
	assert.deepEqual(mapLegacyFact("我叫林舟"), { predicate: "name", object: "林舟" });
	assert.deepEqual(mapLegacyFact("对花生过敏"), { predicate: "allergy", object: "花生" });
	assert.deepEqual(mapLegacyFact("喜欢简洁的回答"), { predicate: "note", object: "喜欢简洁的回答" });
	assert.deepEqual(mapLegacyFact("我的妈妈叫王芳"), { predicate: "relation", object: "王芳", qualifier: "mother" });
});
